def parse(words):
    fo=[]; i=0
    while i<len(words):
        w=words[i]
        if w in flags: fo.append((flags[w],None)); i+=1
        elif w in opts: fo.append((opts[w],words[i+1])); i+=2
        elif w.startswith("--") and "=" in w and w.split("=")[0] in opts:
