        elif w.startswith("-") and len(w)>2 and not w.startswith("--"):
            # bundle: letters are flags, or a flag-letter bundle ending in an option letter
            letters=["-"+c for c in w[1:]]
            if all(l in flags for l in letters): fo.extend((flags[l],None) for l in letters); i+=1
            elif all(l in flags for l in letters[:-1]) and letters[-1] in opts:
                fo.extend((flags[l],None) for l in letters[:-1]); fo.append((opts[letters[-1]],words[i+1])); i+=2
            elif letters[0] in opts: fo.append((opts[letters[0]],w[2:])); i+=1
            else: break
        else: break
    return fo, words[i:]

# ---- ground truth from the binary: how many words did runcon consume as its own? ----
# runcon on a non-SELinux kernel exits 125 with "may be used only on a SELinux kernel" once it has parsed
# everything and decided there is a command; prints the context (rc 0) if there is no command;
# "no command specified" if a context but no command.  We probe with strace to see argv? Not possible (no exec).
# Instead classify outcome and compare with what our parse predicts.
def binary_outcome(words):
    p=subprocess.run(["/usr/bin/runcon",*words],capture_output=True,text=True)
    e=p.stderr
    if "invalid option" in e or "unrecognized option" in e: return "bad-option"
    if "requires an argument" in e: return "missing-arg"
    if "doesn't allow an argument" in e: return "bad-option"
    if "no command specified" in e: return "context-no-command"
    if "SELinux kernel" in e: return "would-exec"
    if p.returncode==0 and p.stdout.strip(): return "print-context"
    return "?"
def predicted(words):
    try: fo,ops=parse(words)
    except IndexError: return "missing-arg"
    ctx_mode = not any(f in ("-c","-t","-u","-r","-l") for f,_ in fo)
    if not ops: return "print-context"
    if ctx_mode and len(ops)==1: return "context-no-command"
    return "would-exec"

